'use strict';
const $=id=>document.getElementById(id), original='1234';
const found=new Set(), openingCodes=new Set();
let attempts=[],tries=0,hintLevel=0;
const hash=code=>[...code].reduce((sum,d)=>sum+Number(d),0)%10;
const valid=code=>typeof code==='string'&&/^[0-9]{4}$/.test(code);
function updateMath(){const c=$('code').value;$('math').textContent=valid(c)?`${[...c].join(' + ')} = ${[...c].reduce((n,d)=>n+Number(d),0)} → hash ${hash(c)}. Stored hash: 0.`:'Enter a four-digit code to inspect its hash here.';}
function seal(){document.body.classList.remove('open');$('treasure').hidden=true;$('gateState').textContent='GATE SEALED';}
function renderHistory(){$('attemptCount').textContent=`${tries} ${tries===1?'try':'tries'}`;$('history').innerHTML=attempts.length?attempts.map(a=>`<li class="${a.open?'success':''}"><code>${a.code}</code><span>${a.open?'Gate opened':'Sealed'}</span></li>`).join(''):'<li class="empty">Your journey starts here.</li>';$('discoveries').textContent=openingCodes.size?`${openingCodes.size} different opening ${openingCodes.size===1?'code':'codes'} discovered`:'No opening codes discovered yet';$('collisionCount').textContent=`Collisions discovered: ${found.size}`;}
function tryCode(code){if(!valid(code)){$('status').textContent='The seal needs exactly four digits, from 0 to 9.';return{error:'Enter exactly four digits.'};}$('code').value=code;updateMath();const h=hash(code),opened=h===0,collision=opened&&code!==original;tries++;if(opened)openingCodes.add(code);if(collision)found.add(code);attempts=[{code,open:opened},...attempts].slice(0,4);renderHistory();if(opened){document.body.classList.add('open');$('treasure').hidden=false;$('gateState').textContent='GATE UNSEALED';$('status').textContent='The seal glows. The treasure is yours!';$('treasureText').textContent=openingCodes.size>1?'Another code opens the same gate. What do your successful codes have in common?':'Golden light spills through the doors. Could a different code open them too?';}else{seal();$('status').textContent='The stone rumbles… but the gate stays sealed. Try another code.';}return{code,unlocked:opened,uniqueOpeningCodes:openingCodes.size};}
function reset(){found.clear();openingCodes.clear();attempts=[];tries=0;hintLevel=0;$('code').value='';$('hints').replaceChildren();$('nextHint').hidden=false;$('nextHint').textContent='Reveal first clue';$('teacher').open=false;if($('secrets').open)$('secrets').close();seal();renderHistory();updateMath();$('status').textContent='The seal awaits your code.';$('code').focus();}
$('form').addEventListener('submit',e=>{e.preventDefault();tryCode($('code').value)});
$('code').addEventListener('input',updateMath);
document.querySelectorAll('[data-digit]').forEach(button=>button.addEventListener('click',()=>{if($('code').value.length<4){$('code').value+=button.dataset.digit;updateMath();}}));
$('clear').onclick=()=>{$('code').value='';updateMath();$('code').focus()};$('backspace').onclick=()=>{$('code').value=$('code').value.slice(0,-1);updateMath();};
$('reset').onclick=reset;$('relock').onclick=()=>{seal();$('code').value='';updateMath();$('status').textContent='The gate is sealed again. Can another code open it?';$('code').focus();};
$('secret').onclick=()=>$('secrets').showModal();$('close').onclick=()=>$('secrets').close();
$('nextHint').onclick=()=>{const clues=['Clue 1: The seal adds your four digits together.','Clue 2: It keeps only the last digit of that total. That short result is called a hash.','Clue 3: Make a total that ends in 0. Different codes can make the same hash!'];if(hintLevel>=clues.length)return;const p=document.createElement('p');p.textContent=clues[hintLevel++];$('hints').append(p);$('nextHint').textContent='Reveal next clue';$('nextHint').hidden=hintLevel===clues.length;};
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'try_hash_passcode',description:'Try a four-digit code at the treasure gate and show whether it opens.',inputSchema:{type:'object',properties:{code:{type:'string',pattern:'^[0-9]{4}$'}},required:['code'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute:({code})=>{if(!valid(code))throw new Error('Code must contain exactly four digits');return tryCode(code)}})).catch(()=>{});}catch{}}
